SELECT a.id AS "id", a.notice_id AS "noticeId", a.user_id AS "userId", a.is_send AS "isSend", a.is_read AS "isRead", a.read_time AS "readTime", a.is_reply AS "isReply", a.reply_time AS "replyTime", a.reply_content AS "replyContent", a.reply_file_ids AS "replyFileIds", n.app_id AS "appId", n.title AS "title", n.type AS "type", n.is_top AS "isTop", n.head_image AS "headImage", n.publish_time AS "publishTime", n.is_reply AS "isNeedReply", n.user_id AS "publishUserId", u.name AS "publishUserName" FROM ${noticePrefix}t_notice_receive_info a
