SELECT a.id AS "id", a.notice_id AS "noticeId", a.user_id AS "userId", a.is_send AS "isSend", a.is_read AS "isRead", a.read_time AS "readTime", a.is_reply AS "isReply", a.reply_time AS "replyTime", a.reply_content AS "replyContent", a.reply_file_ids AS "replyFileIds", n.app_id AS "appId", n.title AS "title", n.type AS "type", n.is_top AS "isTop", n.head_image AS "headImage", n.publish_time AS "publishTime", n.is_reply AS "isNeedReply", n.user_id AS "publishUserId", u.name AS "userName", o.name AS "organName", oc.name AS "companyName" FROM ${noticePrefix}t_notice_receive_info a
LEFT JOIN ${sysPrefix}t_sys_user u ON u.id = a.user_id LEFT JOIN ${sysPrefix}t_sys_organ_extend o ON o.id = u.default_organ_id LEFT JOIN ${sysPrefix}t_sys_organ_extend oc ON oc.id = o.company_id
n.status = #{status} AND a.notice_id = #{noticeId}
AND a.is_read = #{isRead}
AND a.is_reply = #{isReply}
AND n.type IN
#{item,jdbcType=VARCHAR}
AND n.type = #{type}
AND n.is_top = #{isTop}
AND n.biz_mode = #{bizMode}
AND n.title LIKE
'%'||#{title}||'%' CONCAT('%', #{title}, '%') '%'||#{title}||'%' '%'+#{title}+'%'
AND n.content LIKE
'%'||#{content}||'%' CONCAT('%', #{content}, '%') '%'||#{content}||'%' '%'+#{content}+'%'
AND n.publish_time BETWEEN #{startTime} AND #{endTime}
AND n.publish_time >= #{startTime}
AND n.publish_time <= #{endTime}
ORDER BY n.is_top DESC,oc.code ASC,o.code ASC,n.publish_time DESC

